const features = $('Source 1').first().json.features;

// Initialize band summary objects
const bands = {
  minor: { event_count: 0, max_magnitude: -Infinity, max_depth_km: -Infinity },
  moderate: { event_count: 0, max_magnitude: -Infinity, max_depth_km: -Infinity },
  major: { event_count: 0, max_magnitude: -Infinity, max_depth_km: -Infinity }
};

// Process each feature
features.forEach(feature => {
  const mag = feature.properties.mag;
  const depth = feature.geometry.coordinates[2];

  let band;
  if (mag < 4.0) {
    band = 'minor';
  } else if (mag >= 4.0 && mag < 5.0) {
    band = 'moderate';
  } else {
    band = 'major';
  }

  // Update band stats
  const bandStats = bands[band];
  bandStats.event_count++;
  if (mag > bandStats.max_magnitude) {
    bandStats.max_magnitude = mag;
  }
  if (depth > bandStats.max_depth_km) {
    bandStats.max_depth_km = depth;
  }
});

// Build final records, only including bands with events
const records = [];
for (const [bandName, stats] of Object.entries(bands)) {
  if (stats.event_count > 0) {
    records.push({
      magnitude_band: bandName,
      event_count: stats.event_count,
      max_magnitude: stats.max_magnitude,
      max_depth_km: stats.max_depth_km
    });
  }
}

return [{ json: { records } }];
